fn fmt_ptr(p: *const u8) -> String {
    if p.is_null() { "null".to_string() } else { "ptr".to_string() }
}

unsafe fn fmt_cstr(p: *const c_char) -> String {
    if p.is_null() {
        "null".to_string()
    } else {
        format!("{:?}", core::ffi::CStr::from_ptr(p))
    }
}

